// 一致性对照测试基准矩阵
//
// 基准来源：迁移前实现（qr_flutter 4.1.0 内部锁定的 package:qr 3.0.3）
// 对同一输入生成的矩阵 dump 常量（行优先 0/1 串，1 = 深色模块）。
// 重构后引擎输出必须与基准逐位一致，保证矩阵行为不变。
library;

import 'package:antd_qrcode/src/engines/qr/ant_qr_engine.dart';
import 'package:flutter_test/flutter_test.dart';

/// 基准矩阵常量（key = 用例名）
const Map<String, String> _baselines = <String, String>{
  'type1_L': '',
  'type1_M': '',
  'url_M': '',
  'url_L': '',
  'url_Q': '',
  'url_H': '',
  'long_M': '',
  'cjk_M': '',
  'numeric_Q': '',
};

/// 对照用例（内容长度 / 纠错等级 LMQH / 版本全覆盖）
const List<_BaselineCase> _cases = <_BaselineCase>[
    _BaselineCase('type1_L', 'a', AntQrErrorCorrectLevel.l, 21, 1, 2),
    _BaselineCase('type1_M', 'a', AntQrErrorCorrectLevel.m, 21, 1, 3),
    _BaselineCase('url_M', 'https://example.com', AntQrErrorCorrectLevel.m, 25, 2, 5),
    _BaselineCase('url_L', 'https://example.com', AntQrErrorCorrectLevel.l, 25, 2, 3),
    _BaselineCase('url_Q', 'https://example.com', AntQrErrorCorrectLevel.q, 25, 2, 5),
    _BaselineCase('url_H', 'https://example.com', AntQrErrorCorrectLevel.h, 29, 3, 3),
    _BaselineCase(
      'long_M',
      'https://antd-flutter.github.io/antd-flutter/components/qrcode?utm_source=demo&scenario=baseline-consistency-check-2026',
      AntQrErrorCorrectLevel.m,
      45,
      7,
      7,
    ),
    _BaselineCase('cjk_M', '二维码一致性对照测试', AntQrErrorCorrectLevel.m, 29, 3, 4),
    _BaselineCase('numeric_Q', '12345678901234567890', AntQrErrorCorrectLevel.q, 25, 2, 2),
];

void main() {
  group('QR 引擎一致性对照（新旧实现矩阵逐位一致）', () {
    test('引擎输出与迁移前基准一致', () {
      for (final c in _cases) {
        final matrix = AntQrMatrix.fromData(
          data: c.data,
          errorCorrectLevel: c.errorCorrectLevel,
        );
        expect(
          matrix.moduleCount,
          c.moduleCount,
          reason: '${c.name} 模块数不一致',
        );
        expect(
          matrix.typeNumber,
          c.version,
          reason: '${c.name} 版本不一致',
        );
        expect(
          matrix.maskPattern,
          c.maskPattern,
          reason: '${c.name} 掩码模式不一致',
        );

        final bits = StringBuffer();
        for (var row = 0; row < matrix.moduleCount; row++) {
          for (var col = 0; col < matrix.moduleCount; col++) {
            bits.write(matrix.isDark(row, col) ? '1' : '0');
          }
        }
        expect(
          bits.toString(),
          _baselines[c.name],
          reason: '${c.name} 矩阵与迁移前基准不一致',
        );
      }
    });
  });
}

/// 对照用例定义
class _BaselineCase {
  const _BaselineCase(
    this.name,
    this.data,
    this.errorCorrectLevel,
    this.moduleCount,
    this.version,
    this.maskPattern,
  );

  /// 用例名
  final String name;

  /// 二维码内容
  final String data;

  /// 纠错等级（AntQrErrorCorrectLevel 常量）
  final int errorCorrectLevel;

  /// 期望模块数
  final int moduleCount;

  /// 期望版本号
  final int version;

  /// 期望掩码模式
  final int maskPattern;
}
